use winapi::um::winuser::{MessageBoxW, MB_ICONINFORMATION, MB_OK};
use winapi::um::minwindef::UINT;
use winapi::shared::ntdef::LPWSTR;

fn main() {
    let text: LPWSTR = "Hello from Rust using direct WinAPI!".as_ptr() as LPWSTR;
    let caption: LPWSTR = "WinAPI Tool".as_ptr() as LPWSTR;

    unsafe {
        MessageBoxW(
            std::ptr::null_mut(),
            text,
            caption,
            MB_OK | MB_ICONINFORMATION,
        );
    }
}

